import{describe,it,expect}from"vitest";import{SC_HISTORY,CJI_TIMELINE,LANDMARK_JUDGMENTS,CONSTITUTIONAL_POWERS,COURT_HIERARCHY_LEVELS,filterJudgments,getSupremeCourtStats}from"../../frontend/supreme-court-explorer/script.js";describe("Supreme Court History & CJI Datasets",()=>{it("contains historical milestones starting from 1937 Federal Court",()=>{expect(SC_HISTORY.length).toBeGreaterThanOrEqual(4),expect(SC_HISTORY[0].year).toBe("1937"),expect(SC_HISTORY[1].year).toBe("1950")}),it("contains CJI timeline including H.J. Kania and milestone judges",()=>{expect(CJI_TIMELINE.length).toBeGreaterThanOrEqual(4),expect(CJI_TIMELINE[0].name).toContain("Kania")})}),describe("Landmark Judgments Database & Filters",()=>{it("contains key constitutional cases (Kesavananda, Maneka Gandhi, Puttaswamy)",()=>{expect(LANDMARK_JUDGMENTS.length).toBeGreaterThanOrEqual(5);const e=LANDMARK_JUDGMENTS.map(e=>e.caseName);expect(e.some(e=>e.includes("Kesavananda"))).toBe(!0),expect(e.some(e=>e.includes("Puttaswamy"))).toBe(!0),expect(e.some(e=>e.includes("Maneka Gandhi"))).toBe(!0)}),it("filters landmark judgments by query search",()=>{const e=filterJudgments(LANDMARK_JUDGMENTS,"privacy","All Categories");expect(e.length).toBe(1),expect(e[0].caseName).toContain("Puttaswamy");const t=filterJudgments(LANDMARK_JUDGMENTS,"1973","All Categories");expect(t.length).toBe(1),expect(t[0].caseName).toContain("Kesavananda")}),it("filters landmark judgments by category filter",()=>{const e=filterJudgments(LANDMARK_JUDGMENTS,"","Gender Justice & Rights");expect(e.length).toBe(1),expect(e[0].caseName).toContain("Vishaka")})}),describe("Constitutional Jurisdiction & Hierarchy Tiers",()=>{it("defines 4 core jurisdiction types (Original, Writ, Appellate, Advisory)",()=>{expect(CONSTITUTIONAL_POWERS.length).toBe(4);const e=CONSTITUTIONAL_POWERS.map(e=>e.type);expect(e).toContain("Original Jurisdiction"),expect(e).toContain("Writ Jurisdiction"),expect(e).toContain("Appellate Jurisdiction"),expect(e).toContain("Advisory Jurisdiction")}),it("defines 4 tiers of judicial hierarchy from Supreme Court to Munsiff Courts",()=>{expect(COURT_HIERARCHY_LEVELS.length).toBe(4),expect(COURT_HIERARCHY_LEVELS[0].level).toBe(1),expect(COURT_HIERARCHY_LEVELS[0].title).toContain("Supreme Court"),expect(COURT_HIERARCHY_LEVELS[3].level).toBe(4)}),it("computes Supreme Court stats summary accurately",()=>{const e=getSupremeCourtStats();expect(e.sanctionedJudges).toBe(34),expect(e.inaugurationDate).toContain("1950"),expect(e.constitutionalArticle).toBe("Article 124")})});